Here's a basic CartComponent with quantity controls and a checkout button:

```jsx
import React, { useEffect } from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';
import { selectCartItems } from './selectors';

const CartComponent = () => {
  const cartItems = useSelector(selectCartItems);
  const dispatch = useDispatch();

  useEffect(() => {
    const storage = window.localStorage;
    const storedCart = JSON.parse(storage.getItem('cart') || '{}');
    dispatch(addItem(storedCart));
  }, []);

  useEffect(() => {
    window.localStorage.setItem('cart', JSON.stringify(cartItems));
  }, [cartItems]);

  const checkout = () => {
    alert(`You've checked out! Your cart was: ${JSON.stringify(cartItems)}`);
  };

  return (
    <div>
      <h2>Cart</h2>
      {cartItems.map(item => (
        <li key={item.id}>
          <span>{item.name}</span>
          <button onClick={() => dispatch(addItem(item))}>+</button>
          <span>{item.quantity}</span>
          <button onClick={() => dispatch(removeItem(item.id))}>-</button>
        </li>
      ))}
      <button onClick={checkout}>Checkout</button>
    </div>
  );
};

export default CartComponent;
```

Store the cart items in local storage so they persist across page reloads. This keeps state simple and avoids redundant data management logic.

